import copy
def repair(mapping,keys,value):
    if not keys: raise ValueError("path")
    out=copy.deepcopy(mapping); current=out
    for key in keys[:-1]:
        if key not in current: current[key]={}
        if not isinstance(current[key],dict): raise ValueError("intermediate")
        current=current[key]
    current[keys[-1]]=value
    return out

